/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  random,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type CinematicExplosionProps = Record<string, any>;

const CinematicExplosion: React.FC<CinematicExplosionProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  explosionCharacter = "0",
  primaryColor = "#ffffff",
  glowColor = "#00e5ff",
  particleCount = 200,
  explosionSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety checks for parser monotonicity
  const totalFrames = fps * durationInSeconds;
  const buildUpFrames = Math.max(10, Math.floor(Math.min(fps * 1.5, totalFrames * 0.4)));
  const suckInStart = Math.max(5, buildUpFrames - Math.floor(fps * 0.3));

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Text Anticipation Animation (Expand slowly, then snap compress)
  const scaleUp = interpolate(frame, [0, suckInStart], [0.8, 1.3], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });
  const scaleDown = interpolate(frame, [suckInStart, buildUpFrames], [0, -1.1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.in(Easing.exp),
  });
  const textScale = Math.max(0, scaleUp + scaleDown);

  const glowUp = interpolate(frame, [0, suckInStart], [0, 80], {
    extrapolateRight: "clamp",
  });
  const glowDown = interpolate(frame, [suckInStart, buildUpFrames], [0, -80], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textGlow = Math.max(0, glowUp + glowDown);

  const textFadeIn = interpolate(frame, [0, 10], [0, 1], { extrapolateRight: "clamp" });
  const textOpacity = frame >= buildUpFrames ? 0 : textFadeIn;

  // Particle System Logic (Deterministic)
  const particles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const angle = random(`angle-${i}`) * Math.PI * 2;
      const maxDist = random(`dist-${i}`) * Math.max(width, height) * 0.7 + 150;
      const size = random(`size-${i}`) > 0.8
        ? random(`size-large-${i}`) * 15 + 10
        : random(`size-small-${i}`) * 6 + 2;
      const isPrimary = random(`color-${i}`) > 0.5;
      const delay = random(`delay-${i}`) * 4;
      return { id: i, angle, maxDist, size, isPrimary, delay };
    });
  }, [particleCount, width, height]);

  // Global FX (Camera Shake, Screen Flash, Shockwave)
  const isShaking = frame >= buildUpFrames && frame <= buildUpFrames + 12;
  const globalShakeIntensity = isShaking
    ? interpolate(frame, [buildUpFrames, buildUpFrames + 12], [25, 0])
    : 0;
  const globalShakeX = isShaking
    ? random(`shakeX-${frame}`) * globalShakeIntensity - globalShakeIntensity / 2
    : 0;
  const globalShakeY = isShaking
    ? random(`shakeY-${frame}`) * globalShakeIntensity - globalShakeIntensity / 2
    : 0;

  const flashOpacity = interpolate(
    frame,
    [buildUpFrames, buildUpFrames + 2, buildUpFrames + 20],
    [0, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.exp) }
  );

  const shockwaveScale = spring({
    fps,
    frame: Math.max(0, frame - buildUpFrames),
    config: { damping: 25, stiffness: 100, mass: 1 },
  }) * 4;

  const shockwaveOpacity = interpolate(
    frame,
    [buildUpFrames, buildUpFrames + 4, buildUpFrames + 20],
    [0, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        transform: `translate(${globalShakeX}px, ${globalShakeY}px)`,
        transition: "none",
        fontFamily: spaceGrotesk,
      }}
    >
      {/* Background soft glow during anticipation */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          background: `radial-gradient(circle at center, ${glowColor} 0%, transparent 60%)`,
          opacity: frame < buildUpFrames 
            ? interpolate(textScale, [0.8, 1.3], [0, 0.15], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) 
            : 0,
          transition: "none",
        }}
      />

      {/* Explosion Container (Particles & Shockwave) */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 0,
          height: 0,
          zIndex: 20,
        }}
      >
        {/* Shockwave */}
        <div
          style={{
            position: "absolute",
            left: -100,
            top: -100,
            width: 200,
            height: 200,
            borderRadius: "50%",
            border: `6px solid ${glowColor}`,
            boxShadow: `0 0 30px ${glowColor}, inset 0 0 30px ${glowColor}`,
            opacity: shockwaveOpacity,
            transform: `scale(${shockwaveScale})`,
            transition: "none",
          }}
        />

        {/* Particles */}
        {particles.map((p) => {
          const particleFrame = Math.max(0, frame - buildUpFrames - p.delay);
          if (particleFrame === 0 && frame >= buildUpFrames) return null;

          const adjustedFrame = particleFrame * explosionSpeed;

          const progress = spring({
            fps,
            frame: adjustedFrame,
            config: { damping: 14, stiffness: 90, mass: 0.8 },
          });
          const prevProgress = spring({
            fps,
            frame: Math.max(0, adjustedFrame - 1),
            config: { damping: 14, stiffness: 90, mass: 0.8 },
          });

          // Compute distance and stretch particles based on instantaneous velocity
          const dist = progress * p.maxDist;
          const velocity = Math.max(0, (progress - prevProgress) * p.maxDist);
          const stretch = Math.max(1, 1 + velocity * 0.06);

          const pX = Math.cos(p.angle) * dist;
          const pY = Math.sin(p.angle) * dist;

          const pOpacity = interpolate(
            adjustedFrame,
            [0, 3, fps * 0.6, fps * 1.5],
            [0, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const pScale = interpolate(
            adjustedFrame,
            [0, fps * 1.5],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={p.id}
              style={{
                position: "absolute",
                left: -p.size / 2,
                top: -p.size / 2,
                width: p.size,
                height: p.size,
                backgroundColor: p.isPrimary ? primaryColor : glowColor,
                borderRadius: "50%",
                opacity: pOpacity,
                // Rotate aligns the stretch with the trajectory to create "sparks"
                transform: `translate(${pX}px, ${pY}px) rotate(${p.angle}rad) scaleX(${stretch * pScale}) scaleY(${pScale})`,
                boxShadow: `0 0 ${p.size * 1.5}px ${p.isPrimary ? primaryColor : glowColor}`,
                transition: "none",
                willChange: "transform, opacity",
              }}
            />
          );
        })}
      </div>

      {/* Main Character */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
        }}
      >
        <div
          style={{
            transform: `scale(${textScale})`,
            opacity: textOpacity,
            fontSize: Math.min(width, height) * 0.35,
            fontWeight: 700,
            color: primaryColor,
            textShadow: `0 0 ${textGlow}px ${glowColor}, 0 0 ${textGlow * 2}px ${glowColor}`,
            margin: 0,
            lineHeight: 1,
            transition: "none",
          }}
        >
          {explosionCharacter}
        </div>
      </div>

      {/* Cinematic Flash */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          right: 0,
          bottom: 0,
          backgroundColor: glowColor,
          opacity: flashOpacity,
          mixBlendMode: "screen",
          zIndex: 50,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default CinematicExplosion;